1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
63	const DEDUCTIBLE_PER_DAMAGE = 100;
64	const CAP_MULTIPLIER = 2;
65	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
66	const HALF_REIMBURSEMENT_RATE = 0.5;
67	
68	// Money the MHPCO collects and money it pays out are both rounded to whole
69	// gold, always in the MHPCO's favor. That single rule points in opposite
70	// directions depending on which way the coin is travelling, so it gets one
71	// named function per direction rather than a bare Math.ceil/Math.floor at the
72	// call site: the name says *why*, the operator only says *what*.
73	const roundIncomingInMHPCOFavor = (amount: number): number => Math.ceil(amount);
74	
75	const roundOutgoingInMHPCOFavor = (amount: number): number => Math.floor(amount);
76	
77	// The price list: one row per insurable item type. The two numbers are
78	// independent columns — the premium is what the customer pays to insure the
79	// item, the insured value is what the MHPCO would owe for it.
80	interface ItemSpec {
81	  basePremium: number;
82	  insuredValue: number;
83	}
84	
85	const ITEM_SPECS: Record<string, ItemSpec> = {
86	  sword: { basePremium: 100, insuredValue: 1000 },
87	  amulet: { basePremium: 60, insuredValue: 600 },
88	  staff: { basePremium: 80, insuredValue: 800 },
89	  potion: { basePremium: 40, insuredValue: 400 },
90	  rune: { basePremium: 25, insuredValue: 250 },
91	  moonstone: { basePremium: 25, insuredValue: 250 },
92	};
93	
94	const BLOCK_SIZE = 3;
95	const BLOCK_BASE_PREMIUM = 60;
96	
97	// Tallies a collection into "key → how many". Both the premium path (items by
98	// item type) and the claim path (damages by damaged type) ask this same
99	// question, they just reach for the key in a different field.
100	const countBy = <T>(values: T[], keyOf: (value: T) => string): Map<string, number> => {
101	  const counts = new Map<string, number>();
102	  for (const value of values) {
103	    const key = keyOf(value);
104	    counts.set(key, (counts.get(key) ?? 0) + 1);
105	  }
106	  return counts;
107	};
108	
109	const countItemsByType = (items: Item[]): Map<string, number> =>
110	  countBy(items, (item) => item.type);
111	
112	const countDamagesByType = (damages: Damage[]): Map<string, number> =>
113	  countBy(damages, (damage) => damage.itemType);
114	
115	// The single point where an item type is resolved. Every price lookup goes
116	// through here, so an unknown type cannot slip into any calculation.
117	const specOfType = (type: string): ItemSpec => {
118	  const spec = ITEM_SPECS[type];
119	  if (spec === undefined) {
120	    throw new Error(`unknown item type: ${type}`);
121	  }
122	  return spec;
123	};
124	
125	const basePremiumOfType = (type: string): number => specOfType(type).basePremium;
126	
127	const insuredValueOfType = (type: string): number => specOfType(type).insuredValue;
128	
129	const basePremiumOfAlikeItems = (type: string, count: number): number =>
130	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
131	
132	const policyBasePremium = (items: Item[]): number =>
133	  [...countItemsByType(items)].reduce(
134	    (total, [type, count]) => total + basePremiumOfAlikeItems(type, count),
135	    0,
136	  );
137	
138	const firstInsuranceSurcharge = (policyBase: number): number =>
139	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
140	
141	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
142	
143	const isCursed = (item: Item): boolean => item.cursed === true;
144	
145	const isHighlyEnchanted = (item: Item): boolean =>
146	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
147	
148	const curseSurcharge = (item: Item): number =>
149	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
150	
151	const highEnchantmentSurcharge = (item: Item): number =>
152	  isHighlyEnchanted(item)
153	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
154	    : 0;
155	
156	const itemSurchargeTotal = (items: Item[]): number =>
157	  items.reduce(
158	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
159	    0,
160	  );
161	
162	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
163	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
164	    ? policyBase * LOYALTY_DISCOUNT_RATE
165	    : 0;
166	
167	const followUpContractDiscount = (policyBase: number, previousQuotes: number): number =>
168	  previousQuotes > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
169	
170	const policyWideAdjustments = (
171	  policyBase: number,
172	  customer: Customer,
173	  previousQuotes: number,
174	): number =>
175	  firstInsuranceSurcharge(policyBase) -
176	  loyaltyDiscount(policyBase, customer) -
177	  followUpContractDiscount(policyBase, previousQuotes);
178	
179	const quote = (
180	  step: QuoteStep,
181	  customer: Customer,
182	  previousQuotes: number,
183	): QuoteResult => {
184	  const policyBase = policyBasePremium(step.items);
185	  // Intermediate amounts stay fractional; the premium is rounded once, here.
186	  const exactPremium =
187	    policyBase +
188	    itemSurchargeTotal(step.items) +
189	    policyWideAdjustments(policyBase, customer, previousQuotes) +
190	    PROCESSING_FEE;
191	  return { premium: roundIncomingInMHPCOFavor(exactPremium) };
192	};
193	
194	interface Policy {
195	  items: Item[];
196	  remainingCap: number;
197	}
198	
199	const insuranceSum = (items: Item[]): number =>
200	  items.reduce((total, item) => total + insuredValueOfType(item.type), 0);
201	
202	const isHalfCovered = (item: Item): boolean =>
203	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
204	
205	// How much of the damage the policy covers, before the deductible is taken off.
206	const coveredAmount = (damage: Damage, item: Item): number =>
207	  isHalfCovered(item) ? damage.amount * HALF_REIMBURSEMENT_RATE : damage.amount;
208	
209	const payoutForDamage = (damage: Damage, item: Item): number =>
210	  Math.max(0, coveredAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
211	
212	const damagedItem = (policy: Policy, damage: Damage): Item => {
213	  const item = policy.items.find((insured) => insured.type === damage.itemType);
214	  if (item === undefined) {
215	    throw new Error(`damaged item is not covered by the policy: ${damage.itemType}`);
216	  }
217	  return item;
218	};
219	
220	// Every reason an incident can be rejected lives here, so the pricing functions
221	// below can assume they are working on a valid incident. Throws on the first
222	// problem found; nothing has been paid out or decremented at this point.
223	// Returns each damage paired with the insured item it resolved to, so the
224	// pricing pass does not have to look the items up a second time.
225	const validateIncident = (
226	  incident: Incident,
227	  policy: Policy,
228	): { damage: Damage; item: Item }[] => {
229	  const insuredCounts = countItemsByType(policy.items);
230	  for (const [type, damaged] of countDamagesByType(incident.damages)) {
231	    const insured = insuredCounts.get(type);
232	    // An entirely uninsured type is reported by damagedItem below, which gives
233	    // a clearer message than an over-count would.
234	    if (insured !== undefined && damaged > insured) {
235	      throw new Error(`more damages than insured items: ${type}`);
236	    }
237	  }
238	
239	  return incident.damages.map((damage) => {
240	    if (damage.amount < 0) {
241	      throw new Error(`negative damage amount: ${damage.amount}`);
242	    }
243	    return { damage, item: damagedItem(policy, damage) };
244	  });
245	};
246	
247	// A claim is all-or-nothing: the whole incident is validated before any pricing
248	// happens and before the cap is touched, so a claim that turns out to be
249	// invalid cannot leave a partial decrement behind for later steps to inherit.
250	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
251	  const exactPayout = validateIncident(step.incident, policy)
252	    .map(({ damage, item }) => payoutForDamage(damage, item))
253	    .reduce((total, amount) => total + amount, 0);
254	
255	  // Intermediate amounts stay fractional; the payout is rounded once, here,
256	  // after the cap has clamped it — so the figure charged to the cap is the
257	  // same whole number the claimant is handed.
258	  const payout = roundOutgoingInMHPCOFavor(
259	    Math.min(exactPayout, policy.remainingCap),
260	  );
261	  policy.remainingCap -= payout;
262	  return { payout, remainingCap: policy.remainingCap };
263	};
264	
265	const policyFor = (items: Item[]): Policy => ({
266	  items,
267	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
268	});
269	
270	const countQuotesBefore = (steps: Step[], stepIndex: number): number =>
271	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
272	
273	export const runScenario = (scenario: Scenario): ScenarioOutput => {
274	  // A policy is registered under the index of the step that quoted it; that
275	  // step index is the id later claim steps refer to. Claims mutate their
276	  // policy's remainingCap, so the register carries state across steps.
277	  const policies = new Map<number, Policy>();
278	
279	  const results = scenario.steps.map((step, stepIndex): StepResult => {
280	    if (step.op === "claim") {
281	      return claim(step, policies.get(step.policy)!);
282	    }
283	    policies.set(stepIndex, policyFor(step.items));
284	    return quote(
285	      step,
286	      scenario.customer,
287	      countQuotesBefore(scenario.steps, stepIndex),
288	    );
289	  });
290	
291	  return { results };
292	};
