4	// The CLI is a thin shell around runScenario: one scenario in as JSON on stdin,
5	// one result object out as JSON on stdout. All the domain rules live in
6	// claim-office.ts; nothing here decides anything about premiums or payouts.
7	const main = (): void => {
8	  const stdinText = readFileSync(0, "utf8");
9	  const scenario = JSON.parse(stdinText) as Scenario;
10	  process.stdout.write(JSON.stringify(runScenario(scenario)));
11	};
