5	const runCli = (scenario: unknown): string =>
6	  execFileSync("node_modules/.bin/tsx", ["src/cli.ts"], {
7	    input: JSON.stringify(scenario),
8	    encoding: "utf8",
9	  });
10	
11	interface FailedRun {
12	  status: number;
13	  stdout: string;
14	  stderr: string;
15	}
16	
17	const runCliExpectingFailure = (scenario: unknown): FailedRun => {
18	  try {
19	    runCli(scenario);
20	  } catch (error) {
21	    const failure = error as FailedRun;
22	    return {
23	      status: failure.status,
24	      stdout: failure.stdout ?? "",
25	      stderr: failure.stderr ?? "",
26	    };
27	  }
28	  throw new Error("expected the CLI to exit with a non-zero status, but it succeeded");
29	};
